func Parsepbpg(input string, data *pbpgData) error {
	p := newpbpgParser(input, data)

	err := p.stateProgram()
	if err == nil {
		if strings.TrimSpace(p.input[p.pos:]) != "" {
			err = p.errorStack.coalesce()
			return err
		}
	} else {
		err = p.errorStack.coalesce()
	}

	return err
}

type pbpgParser struct {
	input       string
	pos         int
	lineOffsets []int
	Data        *pbpgData
	errorStack  *parserErrorStack

	posStack []int

	// Data, when it implements pbpgSavepointer
	savepoints pbpgSavepointer
}

func newpbpgParser(input string, data *pbpgData) *pbpgParser {
	p := &pbpgParser{
		input:       input,
		lineOffsets: pbpgGenerateLineOffsets(input),
		Data:        data,
		errorStack: &parserErrorStack{
			stack:  make([]parseError, 0, 64),
			scopes: make([]int, 0, 64),
		},
		posStack: make([]int, 0, 64),
	}
	if sp, ok := interface{}(data).(pbpgSavepointer); ok && data != nil {
		p.savepoints = sp
	}
	return p
}

func pbpgGenerateLineOffsets(input string) []int {
	var ret []int

	lines := strings.Split(input, "\n")

	offset := 0
	for _, v := range lines {
		ret = append(ret, len(v)+1+offset)
		offset += len(v) + 1
	}
	return ret
}

